-- SurveyDatabase v14 schema from the Room-generated implementation.
CREATE TABLE gsm_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, ocidUploaded INTEGER NOT NULL, beaconDbUploaded INTEGER NOT NULL, groupNumber INTEGER NOT NULL, mcc INTEGER, mnc INTEGER, lac INTEGER, ci INTEGER, arfcn INTEGER, bsic INTEGER, signalStrength REAL, ta INTEGER, servingCell INTEGER, provider TEXT, slot INTEGER, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE cdma_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, ocidUploaded INTEGER NOT NULL, beaconDbUploaded INTEGER NOT NULL, groupNumber INTEGER NOT NULL, sid INTEGER, nid INTEGER, zone INTEGER, bsid INTEGER, channel INTEGER, pnOffset INTEGER, signalStrength REAL, ecio REAL, servingCell INTEGER, provider TEXT, slot INTEGER, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE umts_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, ocidUploaded INTEGER NOT NULL, beaconDbUploaded INTEGER NOT NULL, groupNumber INTEGER NOT NULL, mcc INTEGER, mnc INTEGER, lac INTEGER, cid INTEGER, uarfcn INTEGER, psc INTEGER, rscp REAL, signalStrength REAL, ecno REAL, servingCell INTEGER, provider TEXT, slot INTEGER, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE lte_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, ocidUploaded INTEGER NOT NULL, beaconDbUploaded INTEGER NOT NULL, groupNumber INTEGER NOT NULL, mcc INTEGER, mnc INTEGER, tac INTEGER, eci INTEGER, earfcn INTEGER, pci INTEGER, rsrp REAL, rsrq REAL, ta INTEGER, servingCell INTEGER, lteBandwidth TEXT, provider TEXT, signalStrength REAL, cqi INTEGER, slot INTEGER, snr REAL, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE nr_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, ocidUploaded INTEGER NOT NULL, beaconDbUploaded INTEGER NOT NULL, groupNumber INTEGER NOT NULL, mcc INTEGER, mnc INTEGER, tac INTEGER, nci INTEGER, narfcn INTEGER, pci INTEGER, ssRsrp REAL, ssRsrq REAL, ssSinr REAL, csiRsrp REAL, csiRsrq REAL, csiSinr REAL, ta INTEGER, servingCell INTEGER, provider TEXT, slot INTEGER, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE wifi_survey_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, beaconDbUploaded INTEGER NOT NULL, sourceAddress TEXT, destinationAddress TEXT, bssid TEXT, beaconInterval INTEGER, serviceSetType TEXT, ssid TEXT, supportedRates TEXT, extendedSupportedRates TEXT, cipherSuites TEXT, akmSuites TEXT, encryptionType TEXT, wps INTEGER, passpoint INTEGER, bandwidth TEXT, channel INTEGER, frequencyMhz INTEGER, signalStrength REAL, snr REAL, nodeType TEXT, standard TEXT, deviceSerialNumber TEXT NOT NULL, deviceName TEXT NOT NULL, deviceTime TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude REAL NOT NULL, missionId TEXT, recordNumber INTEGER NOT NULL, accuracy INTEGER NOT NULL, locationAge INTEGER NOT NULL, speed REAL);
CREATE TABLE tower_cache (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, mcc TEXT, mnc TEXT, area INTEGER NOT NULL, cid INTEGER NOT NULL, timestamp INTEGER NOT NULL, radio TEXT);
CREATE UNIQUE INDEX index_tower_cache_mcc_mnc_area_cid ON tower_cache(mcc, mnc, area, cid);
CREATE TABLE ns_analytics_queue (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, recordType TEXT, protobufJson TEXT, timestamp INTEGER NOT NULL, batchId TEXT, uploaded INTEGER NOT NULL, retryCount INTEGER NOT NULL, lastUploadAttempt INTEGER NOT NULL, payloadSize INTEGER NOT NULL);
CREATE INDEX index_ns_analytics_queue_uploaded ON ns_analytics_queue(uploaded);
CREATE INDEX index_ns_analytics_queue_timestamp ON ns_analytics_queue(timestamp);
CREATE TABLE ns_analytics_connection (workspaceId TEXT NOT NULL PRIMARY KEY, deviceToken TEXT, apiUrl TEXT, deviceId TEXT, registeredAt INTEGER NOT NULL, lastUploadAt INTEGER NOT NULL, totalRecordsUploaded INTEGER NOT NULL, isActive INTEGER NOT NULL, uploadFrequencyMinutes INTEGER NOT NULL);
CREATE TABLE watchlist_entry (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, uuid TEXT, label TEXT, ssid TEXT, bssid TEXT, matchType TEXT, enabled INTEGER NOT NULL, createdAt INTEGER NOT NULL, cooldownSeconds INTEGER NOT NULL, updatedAt INTEGER NOT NULL DEFAULT 0);
CREATE TABLE watchlist_hit (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, entryId INTEGER NOT NULL, label TEXT, matchedField TEXT, ssid TEXT, bssid TEXT, rssi INTEGER NOT NULL, latitude REAL, longitude REAL, timestamp INTEGER NOT NULL, FOREIGN KEY(entryId) REFERENCES watchlist_entry(id) ON UPDATE NO ACTION ON DELETE CASCADE);
CREATE INDEX index_watchlist_hit_entryId_timestamp ON watchlist_hit(entryId, timestamp);
PRAGMA user_version = 14;
